// PORT-STATUS: partial
//
// `OpenGLCellBuilder` creates the cell containers. The generic
// `CellBuilder.Coroutine` (terrain and placed objects) is not ported:
// `OpenGLGfxApi`'s mesh methods are `unimplemented!()`, so `step` reports the
// cell done. `OpenGLX.ToOpenTK` converts
// System.Numerics to OpenTK's maths types; both sides are glam here, so there
// is nothing to convert. `RenderPrimitiveType` is generated by gen_enums.py.
//
// `GL()` stands in for OpenTK's static `GL` class: the host (the egui GL
// control) hands eframe's `glow::Context` to `setGL` before the first draw,
// and every GL call goes through it, on the thread that owns the context.

use std::any::{Any, TypeId};
use std::collections::HashMap;
use std::io::Error;
use std::sync::{Arc, LazyLock, Mutex, OnceLock};
use openx::manager::{CellBuild, CellBuilder};
use openx_gfx::gfx::{AnyArc, IOpenGfxApi};
use openx_poly::core::{BoxFuture, SourceRef};
use crate::engine_open_gl::{OpenGLBackend, OpenGLGfxApi, OpenGLMaterialManager};

static _GL: OnceLock<Arc<glow::Context>> = OnceLock::new();

/// OpenTK's static `GL`: the current context.
pub fn GL() -> &'static glow::Context { _GL.get().expect("no GL context: call setGL first") }

/// Sets the context `GL()` returns. The first context set stays.
pub fn setGL(gl: Arc<glow::Context>) { let _ = _GL.set(gl); }

// #region Extensions

/// C# `Func<ISource, object, bool, MaterialManager<GLRenderMaterial, int>, Task<object>>`.
pub type BuilderByType = for<'a> fn(&'a SourceRef, &'a (dyn Any + Send + Sync), bool, &'a mut OpenGLMaterialManager) -> BoxFuture<'a, Result<AnyArc, Error>>;

/// OpenGLExtensions
pub struct OpenGLX;

impl OpenGLX {
    /// C# `OpenGLX.BuildersByType`, keyed by the path object's type.
    pub fn BuildersByType() -> &'static Mutex<HashMap<TypeId, BuilderByType>> {
        static BuildersByType: LazyLock<Mutex<HashMap<TypeId, BuilderByType>>> = LazyLock::new(Default::default);
        &BuildersByType
    }
}

