/// C# `class OpenGLCellBuilder`.
///
/// `step` returns `false` immediately: the containers exist, and the generic
/// coroutine that would fill them is not ported.
pub struct OpenGLCellBuilder {
    source: SourceRef,
    api: Arc<Mutex<OpenGLGfxApi>>,
}

impl OpenGLCellBuilder {
    pub fn new(source: SourceRef, api: Arc<Mutex<OpenGLGfxApi>>) -> Self { Self { source, api } }
}

impl CellBuilder<OpenGLBackend> for OpenGLCellBuilder {
    fn createContainers(&mut self, name: &str) -> (Option<AnyArc>, Option<AnyArc>) {
        let mut api = self.api.lock().unwrap();
        let obj = api.createObject(name, Some("Cell"), None);
        let objectsObj = api.createObject("objects", None, Some(&obj));
        (obj, objectsObj)
    }

    fn setVisible(&mut self, src: &Option<AnyArc>, visible: bool) { self.api.lock().unwrap().setVisible(src, visible); }

    fn destroy(&mut self, src: &Option<AnyArc>) { self.api.lock().unwrap().destroy(src); }

    fn step(&mut self, _handle: &mut CellBuild<OpenGLBackend>) -> bool { false }
}
